CREATE TABLE extracted_evidence_field_decisions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID NOT NULL REFERENCES organizations(id), record_id UUID NOT NULL REFERENCES extracted_evidence_records(id), field_name TEXT NOT NULL, decision TEXT NOT NULL, reviewed_value JSONB, rationale TEXT NOT NULL, reviewer_id UUID NOT NULL REFERENCES user_profiles(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());